catalog.schema:
{
    "input": {
        "type": "object",
        "oneOf": [
            {
                "properties": {
                    "text": {
                        "oneOf": [
                            {
                                "type": "string",
                                "description": "The text to embed",
                                "minLength": 1
                            },
                            {
                                "type": "array",
                                "description": "Batch of text values to embed",
                                "items": {
                                    "type": "string",
                                    "description": "The text to embed",
                                    "minLength": 1
                                },
                                "maxItems": 100
                            }
                        ]
                    },
                    "pooling": {
                        "type": "string",
                        "enum": [
                            "mean",
                            "cls"
                        ],
                        "default": "mean",
                        "description": "The pooling method used in the embedding process. `cls` pooling will generate more accurate embeddings on larger inputs - however, embeddings created with cls pooling are not compatible with embeddings generated with mean pooling. The default pooling method is `mean` in order for this to not be a breaking change, but we highly suggest using the new `cls` pooling for better accuracy."
                    }
                },
                "required": [
                    "text"
                ]
            },
            {
                "properties": {
                    "requests": {
                        "type": "array",
                        "description": "Batch of the embeddings requests to run using async-queue",
                        "items": {
                            "properties": {
                                "text": {
                                    "oneOf": [
                                        {
                                            "type": "string",
                                            "description": "The text to embed",
                                            "minLength": 1
                                        },
                                        {
                                            "type": "array",
                                            "description": "Batch of text values to embed",
                                            "items": {
                                                "type": "string",
                                                "description": "The text to embed",
                                                "minLength": 1
                                            },
                                            "maxItems": 100
                                        }
                                    ]
                                },
                                "pooling": {
                                    "type": "string",
                                    "enum": [
                                        "mean",
                                        "cls"
                                    ],
                                    "default": "mean",
                                    "description": "The pooling method used in the embedding process. `cls` pooling will generate more accurate embeddings on larger inputs - however, embeddings created with cls pooling are not compatible with embeddings generated with mean pooling. The default pooling method is `mean` in order for this to not be a breaking change, but we highly suggest using the new `cls` pooling for better accuracy."
                                }
                            },
                            "required": [
                                "text"
                            ]
                        }
                    }
                },
                "required": [
                    "requests"
                ]
            }
        ]
    },
    "output": {
        "oneOf": [
            {
                "type": "object",
                "contentType": "application/json",
                "properties": {
                    "shape": {
                        "type": "array",
                        "items": {
                            "type": "number"
                        }
                    },
                    "data": {
                        "type": "array",
                        "description": "Embeddings of the requested text values",
                        "items": {
                            "type": "array",
                            "description": "Floating point embedding representation shaped by the embedding model",
                            "items": {
                                "type": "number"
                            }
                        }
                    },
                    "pooling": {
                        "type": "string",
                        "enum": [
                            "mean",
                            "cls"
                        ],
                        "description": "The pooling method used in the embedding process."
                    }
                }
            },
            {
                "type": "object",
                "contentType": "application/json",
                "title": "Async response",
                "properties": {
                    "request_id": {
                        "type": "string",
                        "description": "The async request id that can be used to obtain the results."
                    }
                }
            }
        ]
    }
}

{
  "input": {
    "oneOf": [
      { "type": "string", "format": "binary" },
      {
        "type": "object",
        "properties": {
          "audio": {
            "type": "array",
            "description": "An array of integers that represent the audio data constrained to 8-bit unsigned integer values",
            "items": {
              "type": "number",
              "description": "A value between 0 and 255"
            }
          }
        },
        "required": ["audio"]
      }
    ]
  },
  "output": {
    "type": "object",
    "contentType": "application/json",
    "properties": {
      "text": { "type": "string", "description": "The transcription" },
      "word_count": { "type": "number" },
      "words": {
        "type": "array",
        "items": {
          "type": "object",
          "properties": {
            "word": { "type": "string" },
            "start": {
              "type": "number",
              "description": "The second this word begins in the recording"
            },
            "end": {
              "type": "number",
              "description": "The ending second when the word completes"
            }
          }
        }
      },
      "vtt": { "type": "string" }
    },
    "required": ["text"]
  }
}

{
    "input": {
        "type": "object",
        "oneOf": [
            {
                "properties": {
                    "text": {
                        "type": "string",
                        "minLength": 1,
                        "description": "The text to be translated"
                    },
                    "source_lang": {
                        "type": "string",
                        "default": "en",
                        "description": "The language code of the source text (e.g., 'en' for English). Defaults to 'en' if not specified"
                    },
                    "target_lang": {
                        "type": "string",
                        "description": "The language code to translate the text into (e.g., 'es' for Spanish)"
                    }
                },
                "required": [
                    "text",
                    "target_lang"
                ]
            },
            {
                "properties": {
                    "requests": {
                        "type": "array",
                        "description": "Batch of the embeddings requests to run using async-queue",
                        "items": {
                            "type": "object",
                            "properties": {
                                "text": {
                                    "type": "string",
                                    "minLength": 1,
                                    "description": "The text to be translated"
                                },
                                "source_lang": {
                                    "type": "string",
                                    "default": "en",
                                    "description": "The language code of the source text (e.g., 'en' for English). Defaults to 'en' if not specified"
                                },
                                "target_lang": {
                                    "type": "string",
                                    "description": "The language code to translate the text into (e.g., 'es' for Spanish)"
                                }
                            },
                            "required": [
                                "text",
                                "target_lang"
                            ]
                        }
                    }
                },
                "required": [
                    "requests"
                ]
            }
        ]
    },
    "output": {
        "type": "object",
        "contentType": "application/json",
        "oneOf": [
            {
                "properties": {
                    "translated_text": {
                        "type": "string",
                        "description": "The translated text in the target language"
                    }
                }
            },
            {
                "type": "object",
                "contentType": "application/json",
                "title": "Async response",
                "properties": {
                    "request_id": {
                        "type": "string",
                        "description": "The async request id that can be used to obtain the results."
                    }
                }
            }
        ]
    }
}

