catalog.sdk_config:
{"inputDefaults":"$merge([input, { "max_tokens": input.max_tokens ? input.max_tokens : (input.stream ? 512 : 512) }])","generatePayload":" ( $payload := [ $tensor("String", [input.prompt], { "shape": [1], "name": "text_input" }), $tensor("String", [$string({ "temperature": input.temperature, "max_tokens": input.max_tokens, "top_p": input.top_p, "top_k": input.top_k, "seed": input.seed, "repetition_penalty": input.repetition_penalty, "frequency_penalty": input.frequency_penalty, "presence_penalty": input.presence_penalty })], { "shape": [1], "name": "sampling_parameters" }) ];
$payload := $append($payload, input.stream ? [ $tensor("Bool", true, { "name": "stream" }) ] : []);
$payload := $append($payload, input.image ? [ $tensor("Uint8", input.image, { "shape": [1, $count(input.image)], "name": "image"}), $tensor("Bool", true, { "name": "exclude_input_in_output" }) ] : []);
$payload ) ","postProcessing":"{ "response": output.name.value[0] }","defaultContext":"defaultContexts.chat","promptTemplate":"chatml"}

catalog.schema:
{
  "input": {
    "oneOf": [{
      "type": "string",
      "format": "binary",
      "description": "Binary string representing the image contents."
    }, {
      "type": "object",
      "properties": {
        "prompt": {
          "type": "string",
          "description": "The input text prompt for the model to generate a response."
        },
        "raw": {
          "type": "boolean",
          "default": false,
          "description": "If true, a chat template is not applied and you must adhere to the specific model's expected formatting."
        },
        "top_p": {
          "type": "number",
          "description": "Controls the creativity of the AI's responses by adjusting how many possible words it considers. Lower values make outputs more predictable; higher values allow for more varied and creative responses."
        },
        "top_k": {
          "type": "number",
          "description": "Limits the AI to choose from the top 'k' most probable words. Lower values make responses more focused; higher values introduce more variety and potential surprises."
        },
        "seed": {
          "type": "number",
          "description": "Random seed for reproducibility of the generation."
        },
        "repetition_penalty": {
          "type": "number",
          "description": "Penalty for repeated tokens; higher values discourage repetition."
        },
        "frequency_penalty": {
          "type": "number",
          "description": "Decreases the likelihood of the model repeating the same lines verbatim."
        },
        "presence_penalty": {
          "type": "number",
          "description": "Increases the likelihood of the model introducing new topics."
        },
        "image": {
          "oneOf": [{
            "type": "array",
            "description": "An array of integers that represent the image data constrained to 8-bit unsigned integer values",
            "items": {
              "type": "number",
              "description": "A value between 0 and 255"
            }
          }, {
            "type": "string",
            "format": "binary",
            "description": "Binary string representing the image contents."
          }]
        },
        "max_tokens": {
          "type": "integer",
          "default": 512,
          "description": "The maximum number of tokens to generate in the response."
        }
      },
      "required": ["image"]
    }]
  },
  "output": {
    "type": "object",
    "contentType": "application/json",
    "properties": {
      "description": {
        "type": "string"
      }
    }
  }
}

