functions.code:
(
$payload := [
  $tensor("String", [args.prompt], { "shape": [1], "name": "text_input" }),
  $tensor("String", [$string({
    "temperature": args.temperature,
    "max_tokens": args.max_tokens,
    "top_p": args.top_p,
    "top_k": args.top_k,
    "seed": args.seed,
    "repetition_penalty": args.repetition_penalty,
    "frequency_penalty": args.frequency_penalty,
    "presence_penalty": args.presence_penalty
    })], { "shape": [1], "name": "sampling_parameters" })
  ];

  $payload := $append($payload, args.stream ? [
    $tensor("Bool", true, { "name": "stream" })
  ] : []);

  $payload := $append($payload, args.image ? [
    $tensor("Uint8", args.image, { "shape": [1, $count(args.image)], "name": "image"}),
    $tensor("Bool", true, { "name": "exclude_input_in_output" })
  ] : []);

  $payload
)

(
  /* https://developer.mozilla.org/en-US/docs/Web/API/WebVTT_API */
  $wordsPerLine := 5;
  $format := "#00.000;(#00.000)";

  $vals := output.name.value;

  /* words and timestamps combined */
  $words := $map($vals, function($w, $i) { (
    $ts := output.timestamps.value[0][$i];
    {
        "word": $trim($w),
        "start": $ts[0],
        "end": $ts[1]
    }
  ) } );

  /* build VTT data */
  $vtt := $map($words, function($w, $i) { (
    (
      /* every $wordsPerLine or at the last word */
      (($i + 1) % $wordsPerLine = 0) or
      ($i = $count(output.name.value) - 1)
    ) ? (
      $start := $formatNumber($words[$i - ($i % $wordsPerLine)].start, $format);
      /*$end := $formatNumber($words[$i].end, $format);*/
      $end := $formatNumber($words[$i].end ? $words[$i].end : $number($words[$i - ($i % $wordsPerLine)].start)+0.001, $format);
      $phrase := $join($map($slice($words, $i - ($i % $wordsPerLine), $i + 1), function($w) { $w.word }), " ");
      /* VTT line */
      "

" & $start & " --> " & $end & "
" & $phrase;
    )
  ) } );
  {
      "text": $trim($join(output.name.value)),
      "word_count": $count($words),
      "vtt": "WEBVTT" & $join($vtt),
      "words": $words
  }
)

(
  input.raw or $not($contains(output, "<tool_call>")) ? { "response": output } : (
    $r := $replace(output, /
/, '');
    $m := $match($r, /<tool_call>(.*?)<\/tool_call>/);
    $calls := $map($m, function($call) { (
      /* attempt to convert into parseable JSON */
      /* preserve the double-quotes returned by the model */
      $json := $replace($call.groups[0],'"','\\"');
      /* replace single-quotes (that are not preceded by a backslash) to double-quotes */
      $json := $replace($json,/([^\x5c])'/,'$1"');
      /* match and replace Python literals with JSON equivalents */
      $json := $replace($json, /('(\x5c'|[^'])*')|None|True|False/, function($literal) {(
        $literal.match = "True" ? "true" : 
        $literal.match = "False" ? "false" :
        $literal.match = "None" ? "null" :
        $literal.match;
      )});
      $json := $jsonParse($json);
      $type($json) = "string" ? { response: $json } : $json;
    )});
  /* filter out calls that we couldnt parse. $jsonParse returned false */
  $calls := [$filter($calls, function($v) { $v != false })];
  input.functions ? (
    $tr := $runCalls($calls, input.functions);
    { "response": null, "tool_calls": $calls, "tool_responses": $tr }
    ) : { "response": null, "tool_calls": $calls }
  )
)
